def fib(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n <= 1:
        return n

    def multiply(a, b):
        return (
            a[0]*b[0] + a[1]*b[1],
            a[0]*b[1] + a[1]*b[0]
        )

    def power(pair, exp):
        if exp == 1:
            return pair
        half = power(pair, exp // 2)
        return multiply(half, half) if exp % 2 == 0 else multiply(half, pair)

    # Base matrix [[1, 1], [1, 0]]
    base = (1, 1)
    result = power(base, n - 1)
    return result[0]
