def fib(n):
    if n <= 0: return 0
    if n == 1: return 1

    def fib_pair(k):
        if k == 0:
            return (0, 1)
        a, b = fib_pair(k >> 1)
        c = a * ((b << 1) - a)
        d = a * a + b * b
        return (c, d) if (k & 1) == 0 else (d, c + d)

    return fib_pair(n)[0]
